#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
import hashlib
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "src" / "CrossSection3DScrollGLB.jsx"
BASE_SHA256 = "ead9ef9b7ea3c1686c9b7113e21a7b8ad35e0b72e3eaee63f7a46e9b68c05341"
FINAL_SHA256 = "6b89042801dde2e2b2d71165f544394d239722e6cfba40f048cadcd3e234b666"
PATCH_GZIP_B64 = ""


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def main() -> int:
    current = SOURCE.read_bytes()
    current_sha = digest(current)
    if current_sha == FINAL_SHA256:
        print(f"v7.5.51 already materialized: {FINAL_SHA256}")
        return 0
    if current_sha != BASE_SHA256:
        print(
            f"Refusing to patch unexpected source: {current_sha}; expected {BASE_SHA256}",
            file=sys.stderr,
        )
        return 2

    patch = gzip.decompress(base64.b64decode(PATCH_GZIP_B64))
    proc = subprocess.run(
        ["git", "apply", "--whitespace=nowarn", "-"],
        cwd=ROOT,
        input=patch,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    if proc.returncode:
        sys.stderr.buffer.write(proc.stderr)
        return proc.returncode

    final_sha = digest(SOURCE.read_bytes())
    if final_sha != FINAL_SHA256:
        print(
            f"Materialized source hash mismatch: {final_sha}; expected {FINAL_SHA256}",
            file=sys.stderr,
        )
        return 3

    print(f"Materialized v7.5.51: {FINAL_SHA256}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
